import{_ as t,o as r,c as s,a2 as a}from"./chunks/framework.DYAmjhAm.js";const c=JSON.parse('{"title":"Versions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/versions.md","filePath":"guide/versions.md","lastUpdated":1790834504000}'),i={name:"guide/versions.md"};function n(o,e,h,l,d,p){return r(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Versions&quot;">​</a></h1><p>Breeze has two current packages: the JavaScript client on npm and the .NET server on NuGet. They were released together, but their version numbers are not the same.</p><table tabindex="0"><thead><tr><th></th><th>Current</th><th>Previous</th></tr></thead><tbody><tr><td><strong>JavaScript client</strong> — npm <a href="https://www.npmjs.com/package/breeze-client" target="_blank" rel="noreferrer"><code>breeze-client</code></a></td><td><strong>3.x</strong> (3.0.0)</td><td>2.x (2.2.2)</td></tr><tr><td><strong>.NET server</strong> — NuGet <a href="https://www.nuget.org/packages/Breeze.AspNetCore.NetCore/" target="_blank" rel="noreferrer"><code>Breeze.*</code></a>, five packages</td><td><strong>8.x</strong> (8.0.0)</td><td>7.x (7.5.2)</td></tr><tr><td><strong>.NET versions</strong> the server targets</td><td>.NET 8, 9 and 10</td><td>.NET 5 to 10</td></tr><tr><td><strong>Source</strong></td><td><a href="https://github.com/Breeze/breeze-client-v3" target="_blank" rel="noreferrer">breeze-client-v3</a>, <a href="https://github.com/Breeze/breeze-server-v3" target="_blank" rel="noreferrer">breeze-server-v3</a></td><td><a href="https://github.com/Breeze/breeze-client" target="_blank" rel="noreferrer">breeze-client</a>, <a href="https://github.com/Breeze/breeze.server.net" target="_blank" rel="noreferrer">breeze.server.net</a></td></tr><tr><td><strong>Documentation</strong></td><td><a href="/breeze-client-v3/">Client</a> (this site), <a href="https://breeze.github.io/breeze-server-v3/" target="_blank" rel="noreferrer">server</a></td><td><a href="https://breeze.github.io/doc-js/?v2" target="_blank" rel="noreferrer">Client 2.x</a>, <a href="https://breeze.github.io/doc-net/?v2" target="_blank" rel="noreferrer">server 7.x</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">The &quot;v3&quot; in the repository names is not a package version</p><p><code>breeze-client-v3</code> publishes <code>breeze-client</code> 3.x, but <code>breeze-server-v3</code> publishes the .NET packages at <strong>8.x</strong>. The server packages kept their own numbering, which was already at 7.</p></div><h2 id="which-versions-work-together" tabindex="-1">Which versions work together <a class="header-anchor" href="#which-versions-work-together" aria-label="Permalink to &quot;Which versions work together&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Server 7.x</th><th>Server 8.x</th></tr></thead><tbody><tr><td><strong>Client 2.x</strong></td><td>Yes</td><td>Yes</td></tr><tr><td><strong>Client 3.x</strong></td><td>Expected to work, not tested</td><td><strong>Yes</strong> — tested together</td></tr></tbody></table><ul><li><strong>Server 8.x works with either client.</strong> Its metadata and JSON formats are unchanged from 7.x. Its error responses are now RFC 9457 problem details, but they still carry the members a 2.x client reads, so a 2.x client sees no difference. You can upgrade the server first.</li><li><strong>Client 3.x is tested against server 8.x only.</strong> It uses the same formats as 7.x, so it is expected to work with a 7.x server, but that pairing is not part of the test suite.</li></ul><h2 id="installing-a-specific-version" tabindex="-1">Installing a specific version <a class="header-anchor" href="#installing-a-specific-version" aria-label="Permalink to &quot;Installing a specific version&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> breeze-client@3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # current</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> breeze-client@2</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # previous</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Breeze.AspNetCore.NetCore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8.0.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dotnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Breeze.Persistence.EFCore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8.0.0</span></span></code></pre></div><p>For .NET 5, 6 or 7, which are out of support, stay on 7.5.2.</p><h2 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h2><ul><li><strong>Client, 2.x to 3.x:</strong> <a href="./migrating-from-2x">Migrating from 2.x</a>. Most applications need only a handful of changes.</li><li><strong>Server, 7.x to 8.x:</strong> <a href="https://github.com/Breeze/breeze-server-v3/blob/master/UPGRADE.md" target="_blank" rel="noreferrer">UPGRADE.md</a> in breeze-server-v3.</li></ul>`,13)])])}const k=t(i,[["render",n]]);export{c as __pageData,k as default};
